/*!
 * icons.js — 图标 404 兜底修复
 * 作用：当 icons/*.png 因部署目录结构问题返回 404 时（例如 GitHub 网页上传把文件夹拍平），
 *       自动把 manifest 与 <link rel="icon"> 换成内联 base64 图标，避免出现「灰底 G」默认图标。
 * 体积：约 210KB，仅在检测到 404 时才被浏览器解码使用。
 */
(function () {
  "use strict";
  var DATA = {
    32: "",
    192: "",
    512: "",
    maskable: "",
    apple: "",
  };
  function uri(key, mime) { return "data:" + (mime || "image/png") + ";base64," + DATA[key]; }

  // 探测 icons/icon-192.png 是否可访问
  var probe = new Image();
  probe.onerror = function () { patch(); };
  probe.onload  = function () { /* 正常，无需修复 */ };
  probe.src = "icons/icon-192.png?probe=" + Date.now();

  function patch() {
    // ① 替换所有 icon / apple-touch-icon 链接
    var head = document.head || document.getElementsByTagName("head")[0];
    var old = head.querySelectorAll('link[rel="icon"], link[rel="apple-touch-icon"], link[rel="shortcut icon"]');
    for (var i = 0; i < old.length; i++) old[i].parentNode.removeChild(old[i]);
    function add(rel, key, sizes) {
      var l = document.createElement("link");
      l.rel = rel; l.type = "image/png";
      if (sizes) l.sizes = sizes;
      l.href = uri(key); head.appendChild(l);
    }
    add("icon", "32", "32x32");
    add("icon", "192", "192x192");
    add("icon", "512", "512x512");
    add("apple-touch-icon", "apple", "180x180");

    // ② 用 Blob URL 生成一个「修正过路径的 manifest」，替换掉原本 404 的那个
    try {
      var mf = {
        name: "旅行规划 · 青甘大环线",
        short_name: "旅行规划",
        description: "行程规划、交通票务、记账、酒店、手账与行程长图，一站式个人旅行管理工具。",
        start_url: "./",
        scope: "./",
        display: "standalone",
        display_override: ["standalone", "minimal-ui"],
        orientation: "portrait-primary",
        theme_color: "#2bb8c4",
        background_color: "#f7fdfd",
        lang: "zh-CN",
        dir: "ltr",
        categories: ["travel", "productivity", "lifestyle"],
        icons: [
          { src: uri("192"), sizes: "192x192", type: "image/png", purpose: "any" },
          { src: uri("512"), sizes: "512x512", type: "image/png", purpose: "any" },
          { src: uri("maskable"), sizes: "512x512", type: "image/png", purpose: "maskable" },
          { src: uri("apple"), sizes: "180x180", type: "image/png", purpose: "any" }
        ],
        shortcuts: [
          { name: "打开行程总览", short_name: "总览", url: "./?view=overview" },
          { name: "记一笔账", short_name: "记账", url: "./?panel=ledger" }
        ]
      };
      var blob = new Blob([JSON.stringify(mf)], { type: "application/manifest+json" });
      var url = URL.createObjectURL(blob);
      var ml = head.querySelector('link[rel="manifest"]');
      if (!ml) { ml = document.createElement("link"); ml.rel = "manifest"; head.appendChild(ml); }
      ml.href = url;
      console.log("%c[icons] 检测到 icons/ 目录 404，已自动改用内联图标与 manifest 修复", "color:#2bb8c4");
    } catch (e) {
      console.warn("[icons] manifest 修复失败（不影响使用）:", e && e.message);
    }
  }
})();
